#include <iostream>
#include <string>
using namespace std;

int main() {
    string s, ans;
    cin >> s;

    for (size_t i = 0; i < s.length(); ++i) {
        if (s[i] == '/') {
            ans += '/';
            while (i + 1 < s.length() && s[i + 1] == '/') {
                ++i;
            }
        } else {
            ans += s[i];
        }
    }

    cout << ans;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s, ans;
    cin >> s;

    for (char c : s) {
        if (c != '/' || ans.empty() || ans.back() != '/') {
            ans += c;
        }
    }

    cout << ans;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int count(const string& s, int start) {
    int ans = 0;
    for (int i = start; i < static_cast<int>(s.length()); i++) {
        if (s[i] == '/')
            ans++;
        else
            break;
    }
    return ans;
}

int main() {
    string s, ans;
    cin >> s;

    for (int i = 0; i < static_cast<int>(s.length()); i++) {
        if (s[i] == '/') {
            int t = count(s, i);
            ans += '/';
            i += t - 1;
        } else {
            ans += s[i];
        }
    }

    cout << ans;
    return 0;
}

